$('#login').onclick=()=>{if(!window.google?.accounts?.oauth2)return alert('Google 登入元件尚未載入。請確認網路與 GitHub Pages 網址。');tokenClient=google.accounts.oauth2.initTokenClient({client_id:cfg.clientId,scope:'https://www.googleapis.com/auth/spreadsheets',callback:async r=>{if(r.error)return showError(new Error(r.error));token=r.access_token;$('#login').classList.add('hidden');$('#logout').classList.remove('hidden');try{await reloadData()}catch(e){showError(e)}}});tokenClient.requestAccessToken({prompt:'consent'})};
