async function request(path,opt={}){if(!token)throw Error('請先登入 Google');let r=await fetch('https://sheets.googleapis.com/v4/spreadsheets/'+encodeURIComponent(cfg.spreadsheetId)+path,{...opt,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json',...(opt.headers||{})},cache:'no-store'});if(!r.ok){let t=await r.text();if(r.status===401)throw Error('授權已過期，請重新登入');throw Error('Google Sheet '+r.status+'：'+t.slice(0,220))}return r.status===204?{}:r.json()}
async function readRange(range){let x=await request('/values/'+encodeURIComponent(range));return x.values||[]}
async function reloadData(){setStatus('正在讀取測試副本…');const result=await Promise.all(Object.values(TABS).map(t=>readRange(`'${t}'!A2:D`)));let next={},idx={};for(let i=0;i<3;i++){let key=Object.keys(TABS)[i],data=[],map={};result[i].forEach((r,n)=>{if(!r[0]||!r[1])return;let obj;try{obj=JSON.parse(r[1])}catch{throw Error(`${TABS[key]} 第 ${n+2} 列資料格式錯誤，停止載入以避免覆寫`)}map[r[0]]={row:n+2,version:r[2]||'',deleted:r[3]==='1'};if(r[3]!=='1')data.push(obj)});next[key]=data;idx[key]=map}store=next;index=idx;promptParts=null;reportResolutions=[];store.projects.sort((a,b)=>(a.order||0)-(b.order||0));setStatus('已連線測試副本；修改只寫入週報專用工作表。');render()}
async function saveEntity(kind,obj,deleted=false){if(loading)throw Error('上一筆操作尚未完成');loading=true;try{const tab=TABS[kind],existing=index[kind][obj.id],stamp=new Date().toISOString();if(existing){let remote=await readRange(`'${tab}'!A${existing.row}:D${existing.row}`),rr=remote[0]||[];if(rr[0]!==obj.id||(rr[2]||'')!==existing.version)throw Error('資料已在其他位置變更，請重新載入後再操作');await request('/values/'+encodeURIComponent(`'${tab}'!A${existing.row}:D${existing.row}`)+'?valueInputOption=RAW',{method:'PUT',body:JSON.stringify({values:[[obj.id,deleted?'':JSON.stringify(obj),stamp,deleted?'1':'']]})})}else{await request('/values/'+encodeURIComponent(`'${tab}'!A:D`)+':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS',{method:'POST',body:JSON.stringify({values:[[obj.id,deleted?'':JSON.stringify(obj),stamp,deleted?'1':'']]})})}await reloadData()}finally{loading=false}}
async function saveBatch(changes){if(loading)throw Error('上一筆操作尚未完成');loading=true;try{let values=[],stamp=new Date().toISOString();for(let c of changes){let info=index[c.kind][c.obj.id];if(!info)throw Error('找不到要修改的資料列');let r=(await readRange(`'${TABS[c.kind]}'!A${info.row}:D${info.row}`))[0]||[];if(r[0]!==c.obj.id||(r[2]||'')!==info.version)throw Error('資料已被其他位置修改，請重新載入');values.push({range:`'${TABS[c.kind]}'!A${info.row}:D${info.row}`,values:[[c.obj.id,c.deleted?'':JSON.stringify(c.obj),stamp,c.deleted?'1':'']]})}if(values.length)await request('/values:batchUpdate',{method:'POST',body:JSON.stringify({valueInputOption:'RAW',data:values})});await reloadData()}finally{loading=false}}
function openModal(title,body,foot,wide=false){$('#modal-root').innerHTML=`<div class="modal-wrap"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="small-btn" id="modalClose">關閉</button></div><div id="modalError"></div>${body}<div class="modal-foot">${foot}</div></section></div>`;$('#modalClose').onclick=closeModal;if($('#modalCancel'))$('#modalCancel').onclick=closeModal}
