function renderRecords(){let rows=store.records.filter(r=>(!filter.from||r.date>=filter.from)&&(!filter.to||r.date<=filter.to)&&(filter.project==='all'||r.project===filter.project)&&(filter.person==='all'||(r.people||[]).includes(filter.person))&&(!filter.text||[r.summary,r.progress,projectName(r.project)].join(' ').toLowerCase().includes(filter.text.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));$('#content').innerHTML=`<div class="stats"><div class="stat"><span>本週紀錄</span><strong>${store.records.filter(r=>r.date>=weekStart&&r.date<=weekEnd).length}<em>筆</em></strong></div><div class="stat"><span>已勾選列入週報</span><strong>${selected().length}<em>筆</em></strong></div><div class="stat"><span>固定追蹤專案</span><strong>${store.projects.length}<em>項</em></strong></div></div><section class="panel"><div class="panel-head"><div><h2>工作紀錄</h2><p>勾選值得長官關注的事項；篩選預設為本週。</p></div><div class="actions"><button class="btn" id="jsonImport">貼上 JSON</button><button class="btn primary" id="addRecord">＋ 新增紀錄</button></div></div><div class="toolbar"><input type="text" id="search" placeholder="搜尋事項或進度" value="${esc(filter.text)}"><select id="pfilter"><option value="all">所有專案</option>${projectOptions(filter.project)}</select><select id="personfilter"><option value="all">所有處理人</option>${PEOPLE.map(p=>`<option ${filter.person===p?'selected':''}>${p}</option>`).join('')}</select><button class="btn" id="clearFilter">本週</button></div><div class="inline-actions" style="margin-bottom:12px"><label>從 <input type="date" id="filterFrom" value="${esc(filter.from)}"></label><label>到 <input type="date" id="filterTo" value="${esc(filter.to)}"></label><button class="btn" id="refresh">重新讀取</button></div>${rows.length?rows.map(r=>`<div class="record"><input type="checkbox" data-check="${esc(r.id)}" aria-label="列入週報 ${esc(r.summary)}" ${r.selected?'checked':''}><div><div class="record-meta"><span>${roc(r.date)}</span><span class="tag ${r.project==='other'?'other':''}">${esc(projectName(r.project))}</span><span>${esc((r.people||[]).join('、'))}</span>${r.isATM?'<span class="tag">ATM異常</span>':''}</div><div class="record-title">${esc(r.summary)}</div><p class="record-detail">${esc(r.progress)}</p></div><div><button class="small-btn" data-edit="${esc(r.id)}">編輯</button><button class="small-btn" data-delete="${esc(r.id)}">刪除</button></div></div>`).join(''):'<div class="empty"><b>沒有符合條件的紀錄</b>新增一筆，或調整篩選條件。</div>'}</section><div class="actions"><button class="btn" id="taskImport">讀取雜事系統</button><button class="btn" id="atmImport">匯入 ATM Excel</button><button class="btn" id="jsonPrompt">複製 JSON 整理指令</button><button class="btn primary" id="goInterview">開始 Gemini 訪談 →</button><button class="btn primary" id="goReport">前往產生週報 →</button></div>`;
$('#search').oninput=e=>{filter.text=e.target.value;let pos=e.target.selectionStart;renderRecords();$('#search').focus();$('#search').setSelectionRange(pos,pos)};$('#pfilter').onchange=e=>{filter.project=e.target.value;renderRecords()};$('#personfilter').onchange=e=>{filter.person=e.target.value;renderRecords()};$('#filterFrom').onchange=e=>{filter.from=e.target.value;renderRecords()};$('#filterTo').onchange=e=>{filter.to=e.target.value;renderRecords()};$('#clearFilter').onclick=()=>{filter={from:weekStart,to:weekEnd,project:'all',person:'all',text:''};render()};$('#refresh').onclick=()=>run(reloadData);$('#addRecord').onclick=()=>recordModal();$('#jsonImport').onclick=jsonImportModal;$('#taskImport').onclick=()=>run(taskPicker);$('#atmImport').onclick=()=>$('#excelFile').click();$('#jsonPrompt').onclick=copyJsonPrompt;$('#goInterview').onclick=()=>switchPage('interview');$('#goReport').onclick=()=>switchPage('report');$$('[data-check]').forEach(x=>x.onchange=()=>run(()=>saveEntity('records',{...store.records.find(r=>r.id===x.dataset.check),selected:x.checked})));$$('[data-edit]').forEach(x=>x.onclick=()=>recordModal(store.records.find(r=>r.id===x.dataset.edit)));$$('[data-delete]').forEach(x=>x.onclick=()=>{if(confirm('刪除這筆紀錄？已保存的歷史 Prompt 不受影響。'))run(()=>saveEntity('records',store.records.find(r=>r.id===x.dataset.delete),true))})}
function recordModal(r){let d=r||{date:today,project:'other',summary:'',progress:'',people:[],selected:false,isATM:false};openModal(r?'編輯紀錄':'新增紀錄',`<div class="fields2"><div class="field"><label for="fdate">日期 *</label><input type="date" id="fdate" value="${esc(d.date)}"></div><div class="field"><label for="fproject">專案或分類 *</label><select id="fproject">${projectOptions(d.project)}</select></div></div><div class="field"><label for="fsummary">事情概要 *</label><input type="text" id="fsummary" value="${esc(d.summary)}"></div><div class="field"><label for="fprogress">處理進度 *</label><textarea id="fprogress" rows="4">${esc(d.progress)}</textarea></div><div class="field"><label>處理人 *（可複選）</label><div class="checks">${owners(d.people)}</div></div><div class="field"><label><input type="checkbox" id="fisATM" ${d.isATM?'checked':''}> 此紀錄是 ATM 線上異常</label><small>產生週報時將引導補充影響範圍。</small></div><div class="field"><label for="fvendor">廠商或外部人員資訊（選填）</label><input type="text" id="fvendor" value="${esc(d.vendor||'')}"></div><div class="fields2"><div class="field"><label for="fmilestone">新時程的里程碑名稱（選填）</label><input type="text" id="fmilestone" value="${esc(d.scheduleProposal?.name||'')}"></div><div class="field"><label for="ftime">本筆提到的新時程（選填）</label><input type="text" id="ftime" value="${esc(d.scheduleProposal?.value||'')}"></div></div>`,`<button class="btn" id="modalCancel">取消</button><button class="btn primary" id="saveRecord">儲存紀錄</button>`);if(!r)$('#fproject').onchange=()=>{let p=store.projects.find(x=>x.id===$('#fproject').value);$$('[name=owner]').forEach(el=>el.checked=!!p&&(p.owners||[]).includes(el.value))};$('#saveRecord').onclick=async()=>{let obj={...d,id:d.id||id(),date:$('#fdate').value,project:$('#fproject').value,summary:$('#fsummary').value.trim(),progress:$('#fprogress').value.trim(),people:$$('[name=owner]:checked').map(x=>x.value),isATM:$('#fisATM').checked,vendor:$('#fvendor').value.trim(),scheduleProposal:$('#ftime').value.trim()?{name:$('#fmilestone').value.trim(),value:$('#ftime').value.trim(),date:$('#fdate').value}:null};if(!obj.date||!obj.summary||!obj.progress||!obj.people.length)return modalError('日期、事情概要、處理進度與處理人都必填。');try{await saveEntity('records',obj);closeModal()}catch(e){modalError(e.message)}}}
function renderProjects(){$('#content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>固定追蹤專案</h2><p>名稱、需求號、預設處理人與里程碑均可自行管理。</p></div><button class="btn primary" id="addProject">＋ 新增專案</button></div><div class="grid2">${store.projects.map((p,i)=>`<article class="project-card"><div class="project-head"><div><span class="tag">${esc(p.request||'需求號未填')}</span><h3>${esc(p.name)}</h3></div><span class="subtext">${String(i+1).padStart(2,'0')}</span></div><p>${(p.milestones||[]).filter(m=>m.show).map(m=>esc(m.name+'：'+m.value)).join('　')||'尚未選擇顯示時程'}${(p.owners||[]).length?' · '+esc(p.owners.join('、')):''}</p><div class="project-actions"><button class="small-btn" data-up="${p.id}" ${i===0?'disabled':''}>↑ 上移</button><button class="small-btn" data-down="${p.id}" ${i===store.projects.length-1?'disabled':''}>↓ 下移</button><button class="small-btn" data-pedit="${p.id}">編輯</button><button class="small-btn" data-pdelete="${p.id}">移除</button></div></article>`).join('')}</div></section>`;$('#addProject').onclick=()=>projectModal();$$('[data-pedit]').forEach(b=>b.onclick=()=>projectModal(store.projects.find(p=>p.id===b.dataset.pedit)));$$('[data-pdelete]').forEach(b=>b.onclick=()=>removeProject(b.dataset.pdelete));async function move(pid,d){let i=store.projects.findIndex(x=>x.id===pid),j=i+d;if(j<0||j>=store.projects.length)return;let a=store.projects[i],b=store.projects[j];await saveBatch([{kind:'projects',obj:{...a,order:b.order}},{kind:'projects',obj:{...b,order:a.order}}])}$$('[data-up]').forEach(b=>b.onclick=()=>run(()=>move(b.dataset.up,-1)));$$('[data-down]').forEach(b=>b.onclick=()=>run(()=>move(b.dataset.down,1)))}
function projectModal(p){let d=p||{name:'',request:'',owners:[],milestones:[]};let ms=(d.milestones||[]).map(x=>({...x}));function milestones(){return ms.map((m,i)=>`<div class="formgrid rowborder"><div class="field"><label>里程碑名稱</label><input type="text" data-mname="${i}" value="${esc(m.name)}" placeholder="例如正式上線"></div><div class="field"><label>預計時間</label><input type="text" data-mvalue="${i}" value="${esc(m.value)}" placeholder="例如 116年6月"></div><label><input type="checkbox" data-mshow="${i}" ${m.show?'checked':''}> 週報顯示</label><button class="small-btn" data-mdelete="${i}">移除里程碑</button></div>`).join('')}
openModal(p?'編輯專案':'新增專案',`<div class="field"><label for="pname">專案名稱 *</label><input type="text" id="pname" value="${esc(d.name)}"></div><div class="field"><label for="preq">需求號</label><input type="text" id="preq" value="${esc(d.request)}"></div><div class="field"><label>預設處理人</label><div class="checks">${owners(d.owners||[],'po')}</div></div><div class="field"><label>里程碑</label><div id="milestones">${milestones()}</div><button class="btn" id="addMilestone">＋ 新增里程碑</button></div>`,`<button class="btn" id="modalCancel">取消</button><button class="btn primary" id="saveProject">儲存專案</button>`);function bindMs(){const wrap=$('#milestones');wrap.innerHTML=milestones();$$('[data-mname]').forEach(x=>x.oninput=()=>ms[+x.dataset.mname].name=x.value);$$('[data-mvalue]').forEach(x=>x.oninput=()=>ms[+x.dataset.mvalue].value=x.value);$$('[data-mshow]').forEach(x=>x.onchange=()=>ms[+x.dataset.mshow].show=x.checked);$$('[data-mdelete]').forEach(x=>x.onclick=()=>{ms.splice(+x.dataset.mdelete,1);bindMs()})}bindMs();$('#addMilestone').onclick=()=>{ms.push({id:id(),name:'',value:'',show:false});bindMs()};$('#saveProject').onclick=async()=>{let name=$('#pname').value.trim();if(!name)return modalError('請填寫專案名稱。');if(store.projects.some(x=>x.name===name&&x.id!==d.id))return modalError('專案名稱已存在。');if(ms.some(m=>!m.name.trim()||!m.value.trim()))return modalError('里程碑名稱與時間都必須填寫。');for(let m of ms){let old=(d.milestones||[]).find(x=>x.id===m.id);if(!old)m.updatedOn=today;if(old&&old.value!==m.value){m.changes=[...(m.changes||[]),{date:today,old:old.value,new:m.value}];m.updatedOn=today}}let obj={...d,id:d.id||id(),name,request:$('#preq').value.trim(),owners:$$('[name=po]:checked').map(x=>x.value),milestones:ms,milestoneSelectionSet:true,order:d.order||Math.max(0,...store.projects.map(x=>x.order||0))+1};try{await saveEntity('projects',obj);closeModal()}catch(e){modalError(e.message)}}}
async function removeProject(pid){let p=store.projects.find(x=>x.id===pid),rs=store.records.filter(r=>r.project===pid),hs=store.history.filter(h=>(h.parts||[]).some(x=>x.projectId===pid));if(!confirm(`移除「${p.name}」？將刪除 ${rs.length} 筆週報紀錄，並清除 ${hs.length} 份歷史 Prompt 的專案區塊。雜事原資料不受影響。`))return;let changes=[{kind:'projects',obj:p,deleted:true},...rs.map(obj=>({kind:'records',obj,deleted:true})),...hs.map(h=>({kind:'history',obj:{...h,parts:h.parts.filter(x=>x.projectId!==pid)}}))];await run(()=>saveBatch(changes))}
async function appendRows(kind,objs){if(!objs.length)return;if(loading)throw Error('上一筆操作尚未完成');loading=true;try{const stamp=new Date().toISOString();await request('/values/'+encodeURIComponent(`'${TABS[kind]}'!A:D`)+':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS',{method:'POST',body:JSON.stringify({values:objs.map(o=>[o.id,JSON.stringify(o),stamp,''])})});await reloadData()}finally{loading=false}}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true}catch{openModal('請手動複製',`<p class="subtext">瀏覽器未允許自動複製，請選取下方文字。</p><textarea rows="12" readonly>${esc(text)}</textarea>`,`<button class="btn" id="modalCancel">關閉</button>`);return false}}
async function copyJsonPrompt(){let t=`請把我的日常工作紀錄整理成 JSON 陣列，只輸出 JSON，不要增加推測。每筆包含：日期（YYYY-MM-DD）、專案名稱、事情概要、處理進度、處理人（陣列）、里程碑名稱（可空白）、預計時程（可空白）。\n專案名稱候選：${store.projects.map(p=>p.name).join('、')}、補充其它。\n處理人只能從 ${PEOPLE.join('、')} 選擇，可多人；不確定時留空。時程只在紀錄明確提到時填寫，不要把其他日期當成時程。\n範例：[{"日期":"2026-11-04","專案名稱":"補充其它","事情概要":"事項","處理進度":"處理狀況","處理人":["宏全"],"里程碑名稱":"","預計時程":""}]`;if(await copyText(t))alert('已複製 JSON 整理指令。')}
function sim(a,b){let A=String(a||'').toLowerCase().replace(/[^\p{L}\p{N}]/gu,''),B=String(b||'').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');if(!A||!B)return 0;if(A===B)return 1;let x=new Set([...A]),y=new Set([...B]);return 2*[...x].filter(c=>y.has(c)).length/(x.size+y.size)}
function suggestProject(n){if(!n)return {id:'',needsConfirm:true};if(n==='補充其它'||n==='其他')return {id:'other',needsConfirm:false};let p=store.projects.find(x=>x.name===n);if(p)return {id:p.id,needsConfirm:false};let list=store.projects.map(p=>({p,score:sim(n,p.name)})).sort((a,b)=>b.score-a.score);return {id:list[0]?.score>=.4?list[0].p.id:'',needsConfirm:true}}
function jsonImportModal(){openModal('貼上 JSON',`<p class="subtext">可一次匯入多筆。格式需為陣列；找不到專案或處理人時，下一步可自行確認。</p><textarea id="jsonInput" rows="12" spellcheck="false" placeholder='[{"日期":"2026-11-04","專案名稱":"補充其它","事情概要":"...","處理進度":"...","處理人":["宏全"]}]'></textarea>`,`<button class="btn" id="modalCancel">取消</button><button class="btn primary" id="parseJSON">下一步：確認資料</button>`);$('#parseJSON').onclick=()=>{let a;try{a=JSON.parse($('#jsonInput').value)}catch(e){return modalError('JSON 格式錯誤：'+e.message)}if(!Array.isArray(a))return modalError('最外層請使用 JSON 陣列。');let drafts=a.map(x=>{let pname=x['專案名稱']||'',p=suggestProject(pname),who=Array.isArray(x['處理人'])?x['處理人']:x['處理人']?[x['處理人']]:[];return {include:true,date:String(x['日期']||'').replaceAll('/','-'),project:p.id,projectInput:pname,projectConfirm:!p.needsConfirm,summary:String(x['事情概要']||''),progress:String(x['處理進度']||''),people:[...new Set(who.filter(v=>PEOPLE.includes(v)))],vendor:[...new Set(who.filter(v=>!PEOPLE.includes(v)))].join('、'),isATM:Boolean(x['ATM異常']),milestoneName:String(x['里程碑名稱']||''),milestoneValue:String(x['預計時程']||''),source:'JSON'}});importReview(drafts)}}
function importReview(drafts){let body=`<p class="subtext">請逐筆確認；選取的資料會匯入，但不會自動勾選列入週報。相同日期、專案、概要、進度和處理人的紀錄會自動跳過。</p><div class="hint">批次填入日期和處理人後，仍可逐筆調整。來源日期不明的子項目，選取即代表你確認它屬於本週。</div><div class="inline-actions" style="margin:14px 0"><label>批次日期 <input id="batchDate" type="date" value="${today}"></label><button class="btn" id="applyDate">套用至已選</button><span>批次處理人</span><div class="checks">${owners([],'batchOwner')}</div><button class="btn" id="applyOwners">套用至已選</button></div><div id="drafts"></div>`;openModal('匯入確認',body,`<button class="btn" id="modalCancel">取消</button><button class="btn primary" id="confirmImport">匯入已選紀錄</button>`,true);
function renderDrafts(){let root=$('#drafts');root.innerHTML=drafts.map((d,i)=>`<article class="sourceitem"><div class="inline-actions"><label><input type="checkbox" data-include="${i}" ${d.include?'checked':''}> 匯入第 ${i+1} 筆</label><span class="subtext">${esc(d.source||'')}</span></div><div class="formgrid"><div class="field"><label>日期 *</label><input type="date" data-date="${i}" value="${esc(d.date)}"></div><div class="field"><label>專案或分類 *</label><select data-proj="${i}"><option value="">請選擇</option>${projectOptions(d.project)}</select>${!d.projectConfirm?`<small>原名稱：${esc(d.projectInput||'未提供')}；${d.project?'推薦值尚待確認':'請選擇專案'}。</small><label><input type="checkbox" data-confirm="${i}"> 我已確認分類</label>`:''}</div><div class="field"><label>事情概要 *</label><input type="text" data-summary="${i}" value="${esc(d.summary)}"></div><div class="field"><label>處理進度 *</label><textarea data-progress="${i}" rows="3">${esc(d.progress)}</textarea></div><div class="field"><label>處理人 *</label><div class="checks">${owners(d.people||[],`owner-${i}`)}</div></div><div class="field"><label>廠商或外部人員</label><input type="text" data-vendor="${i}" value="${esc(d.vendor||'')}"></div>${d.milestoneValue?`<div class="field"><label>新時程</label><input type="text" data-time="${i}" value="${esc(d.milestoneValue)}"></div><div class="field"><label>里程碑名稱</label><input type="text" data-mname="${i}" value="${esc(d.milestoneName||'')}" placeholder="例如正式上線"></div>`:''}</div><label><input type="checkbox" data-atm="${i}" ${d.isATM?'checked':''}> ATM 線上異常</label></article>`).join('')||'<div class="empty">沒有可匯入的資料。</div>';
for(let i=0;i<drafts.length;i++){let d=drafts[i],one=(attr,handler)=>{let x=root.querySelector(`[data-${attr}="${i}"]`);if(x)x.oninput=handler};one('include',e=>d.include=e.target.checked);one('date',e=>d.date=e.target.value);one('proj',e=>{d.project=e.target.value;d.projectConfirm=true;renderDrafts()});one('confirm',e=>d.projectConfirm=e.target.checked);one('summary',e=>d.summary=e.target.value);one('progress',e=>d.progress=e.target.value);one('vendor',e=>d.vendor=e.target.value);one('time',e=>d.milestoneValue=e.target.value);one('mname',e=>d.milestoneName=e.target.value);one('atm',e=>d.isATM=e.target.checked);root.querySelectorAll(`[name="owner-${i}"]`).forEach(x=>x.onchange=()=>d.people=[...root.querySelectorAll(`[name="owner-${i}"]:checked`)].map(x=>x.value))}}
renderDrafts();$('#applyDate').onclick=()=>{let d=$('#batchDate').value;drafts.filter(x=>x.include).forEach(x=>x.date=d);renderDrafts()};$('#applyOwners').onclick=()=>{let a=$$('[name=batchOwner]:checked').map(x=>x.value);if(!a.length)return alert('請先選擇處理人。');drafts.filter(x=>x.include).forEach(x=>x.people=a);renderDrafts()};$('#confirmImport').onclick=async()=>{let selectedDrafts=drafts.filter(d=>d.include);if(!selectedDrafts.length)return modalError('請先選擇要匯入的紀錄。');for(let i=0;i<selectedDrafts.length;i++){let d=selectedDrafts[i];if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!d.project||!d.projectConfirm||!d.summary.trim()||!d.progress.trim()||!d.people?.length)return modalError(`已選第 ${i+1} 筆尚未完成日期、專案確認、概要、進度或處理人。`)}
let sameDay=new Map();for(let d of selectedDrafts.filter(x=>x.milestoneValue)){let k=[d.project,d.milestoneName,d.date].join('|');if(sameDay.has(k)&&sameDay.get(k)!==d.milestoneValue)return modalError('同一專案與里程碑在同一天有不同新時程，請先確認並調整後再匯入。');sameDay.set(k,d.milestoneValue)}let key=r=>JSON.stringify([r.date,r.project,r.summary.trim(),r.progress.trim(),[...r.people].sort()]);let keys=new Set(store.records.map(key)),pending=[],skipped=0,proposals=[];for(let d of selectedDrafts){let r={id:id(),date:d.date,project:d.project,summary:d.summary.trim(),progress:d.progress.trim(),people:d.people,isATM:!!d.isATM,vendor:d.vendor||'',source:d.source||'',scheduleProposal:d.milestoneValue?{name:d.milestoneName||'',value:d.milestoneValue,date:d.date}:null,selected:false};if(keys.has(key(r))){skipped++;continue}keys.add(key(r));pending.push(r);if(d.milestoneValue&&d.project!=='other')proposals.push({projectId:d.project,date:d.date,name:d.milestoneName||'',value:d.milestoneValue,recordId:r.id})}let suspected=pending.flatMap(r=>store.records.filter(old=>old.source&&r.source&&old.source!==r.source&&sim(old.summary,r.summary)>=.72).map(old=>`${r.summary} ↔ ${old.summary}`));if(suspected.length&&!confirm(`發現不同來源可能重複：\n${suspected.slice(0,5).join('\n')}\n仍匯入已選紀錄？若要調整，請取消並取消勾選。`))return;try{await appendRows('records',pending);closeModal();alert(`已匯入 ${pending.length} 筆；跳過 ${skipped} 筆完全重複紀錄。`);if(proposals.length)timeUpdates(proposals)}catch(e){modalError(e.message)}}}
function timeUpdates(proposals){const uniq=new Map();for(let p of proposals){let k=p.projectId+'|'+p.name;if(!uniq.has(k)||uniq.get(k).date<p.date)uniq.set(k,p)}let ps=[...uniq.values()];openModal('確認專案時程異動',`<p class="subtext">紀錄已匯入。請逐項選擇要更新的時程；未勾選的專案主檔不變。</p>${ps.map((a,i)=>{let p=store.projects.find(x=>x.id===a.projectId);return `<div class="sourceitem"><label><input type="checkbox" data-time-check="${i}"> 更新 ${esc(p?.name||'')}</label><div class="fields2"><div class="field"><label>里程碑</label><select data-time-target="${i}"><option value="">請選擇</option><option value="__new">新增里程碑</option>${(p?.milestones||[]).map(m=>`<option value="${esc(m.id)}" ${m.name===a.name?'selected':''}>${esc(m.name)}（原時程：${esc(m.value)}）</option>`).join('')}</select></div><div class="field"><label>新時程（紀錄日期 ${roc(a.date)}）</label><input data-time-new="${i}" value="${esc(a.value)}"></div><div class="field"><label>新增里程碑名稱</label><input data-time-name="${i}" value="${esc(a.name||'')}" placeholder="選擇新增時必填"></div></div></div>`}).join('')}`,`<button class="btn" id="modalCancel">不更新</button><button class="btn primary" id="applyTimes">確認所選異動</button>`,true);$('#applyTimes').onclick=async()=>{let changes=new Map();for(let i=0;i<ps.length;i++){if(!$(`[data-time-check="${i}"]`).checked)continue;let a=ps[i],mid=$(`[data-time-target="${i}"]`).value,value=$(`[data-time-new="${i}"]`).value.trim();if(!mid||!value)return modalError('請為每個勾選項目選擇里程碑並填入時程。');let p=changes.get(a.projectId)||structuredClone(store.projects.find(x=>x.id===a.projectId));p.milestones=p.milestones||[];let m;if(mid==='__new'){let name=$(`[data-time-name="${i}"]`).value.trim();if(!name)return modalError('請填寫新增里程碑的名稱。');m={id:id(),name,value:'',show:false};p.milestones.push(m);p.milestoneSelectionSet=false}else{m=p.milestones.find(x=>x.id===mid)}if(m.updatedOn&&a.date<m.updatedOn){return modalError(`「${p.name}」收到較舊紀錄，不可覆蓋較新的時程。`)}m.changes=m.changes||[];if(m.value)m.changes.push({date:a.date,old:m.value,new:value});m.value=value;m.updatedOn=a.date;changes.set(p.id,p);a.resolvedName=m.name}try{let rows=[...changes.values()].map(obj=>({kind:'projects',obj}));for(let a of ps.filter(x=>x.resolvedName)){let rec=store.records.find(r=>r.id===a.recordId);if(rec)rows.push({kind:'records',obj:{...rec,scheduleProposal:{...rec.scheduleProposal,name:a.resolvedName}}})}await saveBatch(rows);closeModal()}catch(e){modalError(e.message)}}}
function asDate(v){let m=String(v||'').match(/(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})/);return m?`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`:''}
function weekLogs(raw){let segments=String(raw||'').split(/(?=\[\d{4}[\/-]\d{1,2}[\/-]\d{1,2}\s)/);return segments.filter(x=>{let d=asDate(x);return d&&d>=weekStart&&d<=weekEnd}).map(x=>x.trim())}
async function taskPicker(){setStatus('正在讀取雜事系統原始案件（唯讀）…');let [rows,subrows]=await Promise.all([readRange("'案件總表'!A2:O"),readRange("'子項目清單'!A2:E")]);let cases=rows.filter(r=>r[0]&&r[4]&&!String(r[0]).includes('作廢')).map(r=>({status:r[0],category:r[1]||'',title:r[4]||'',last:r[8]||r[7]||'',logs:weekLogs(r[9]),vendor:r[11]||'',owner:r[12]||'',taskId:r[13]||'',subs:subrows.filter(x=>r[13]&&x[0]===r[13]&&x[1]).map(x=>({content:x[1],deadline:x[2]||'',done:String(x[3]).toUpperCase()==='TRUE',created:x[4]||''}))}));let showAll=false,marked={};setStatus('已讀取雜事案件。原始資料只讀取，不會回寫。');openModal('選擇雜事案件',`<div class="inline-actions"><label><input id="allCases" type="checkbox"> 查看所有案件</label><input type="text" id="caseSearch" placeholder="搜尋案件名稱"></div><p class="subtext">預設顯示未結案及本週有更新的已結案案件。子項目變更可能沒有時間，選取前請確認屬於本週。</p><div id="caseList"></div>`,`<button class="btn" id="modalCancel">取消</button><button class="btn primary" id="chooseCases">下一步：確認匯入</button>`,true);
function draw(){let query=$('#caseSearch').value.trim().toLowerCase();$('#caseList').innerHTML=cases.map((c,i)=>({c,i})).filter(({c})=>(showAll||!c.status.includes('結案')||(asDate(c.last)>=weekStart&&asDate(c.last)<=weekEnd)||c.logs.length>0)&&(!query||c.title.toLowerCase().includes(query))).map(({c,i})=>`<div class="sourceitem"><label><input type="checkbox" data-case="${i}" ${marked[i]?.include?'checked':''}> <strong>${esc(c.title)}</strong>　<span class="tag">${esc(c.status)}</span></label>${marked[i]?.include?`<div class="hint">本週歷程：${c.logs.length?esc(c.logs.join('；')):'沒有可辨識的本週歷程，請在下一步補充。'}${c.taskId?'':'（此案件缺少關聯 ID，無法自動顯示子項目。）'}</div>${c.subs.map((s,j)=>`<label style="display:block;padding:5px 0"><input type="checkbox" data-sub="${i}:${j}" ${marked[i]?.subs?.includes(j)?'checked':''}> ${esc(s.content)}（${s.done?'已完成':'未完成'}；變更日期需自行確認）</label>`).join('')}`:''}</div>`).join('')||'<div class="empty">沒有符合條件的案件。</div>';$$('[data-case]').forEach(x=>x.onchange=()=>{let i=+x.dataset.case;marked[i]={include:x.checked,subs:marked[i]?.subs||[]};draw()});$$('[data-sub]').forEach(x=>x.onchange=()=>{let [i,j]=x.dataset.sub.split(':').map(Number);let a=marked[i].subs;a=x.checked?[...new Set([...a,j])]:a.filter(v=>v!==j);marked[i].subs=a})}draw();$('#allCases').onchange=e=>{showAll=e.target.checked;draw()};$('#caseSearch').oninput=draw;$('#chooseCases').onclick=()=>{let ds=Object.entries(marked).filter(([k,v])=>v.include).map(([k,v])=>{let c=cases[+k],subs=v.subs.map(i=>c.subs[i]),who=PEOPLE.includes(c.owner)?[c.owner]:[];return {include:true,date:'',project:'other',projectConfirm:true,summary:c.title,progress:[...c.logs,...subs.map(s=>`${s.content}（${s.done?'已完成':'未完成'}）`)].join('；'),people:who,vendor:[c.vendor,c.owner&&!PEOPLE.includes(c.owner)?c.owner:''].filter(Boolean).join('／'),isATM:false,source:'雜事系統',milestoneName:'',milestoneValue:''}});if(!ds.length)return modalError('請先選擇案件。');importReview(ds)}}
$('#excelFile').onchange=async e=>{let file=e.target.files[0];e.target.value='';if(!file)return;try{if(!window.XLSX)throw Error('Excel 解析元件未載入');let book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});if(book.SheetNames.length!==1)throw Error('此功能預期 Excel 恰有一個工作表，請檢查檔案。');let rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{header:1,defval:'',raw:false});if(rows.length<2)throw Error('檔案沒有可匯入資料');excelMapping(rows)}catch(e){showError(e)}};
function excelMapping(rows){let heads=rows[0].map(String);const fields=[['status','目前狀態'],['vendor','廠商名稱'],['location','郵局局名'],['machine','機號(3碼英數字)'],['description','問題描述'],['analysis','廠商分析'],['solution','解決方法']];let mapping={};for(let [key,name] of fields)mapping[key]=heads.indexOf(name);openModal('對應 ATM Excel 欄位',`<p class="subtext">若欄名不同，請手動選擇。缺少資料可以在下一步自行補上。</p>${fields.map(([k,n])=>`<div class="field"><label>${n}</label><select id="map-${k}"><option value="-1">檔案沒有此欄</option>${heads.map((h,i)=>`<option value="${i}" ${mapping[k]===i?'selected':''}>${esc(h||'未命名欄 '+(i+1))}</option>`).join('')}</select></div>`).join('')}`,`<button class="btn" id="modalCancel">取消</button><button class="btn primary" id="toExcel">下一步：選取案件</button>`,true);$('#toExcel').onclick=()=>{for(let [k] of fields)mapping[k]=+$('#map-'+k).value;let parsed=rows.slice(1).filter(r=>r.some(v=>String(v).trim())).map(r=>{let o={};for(let [k] of fields)o[k]=mapping[k]>=0?String(r[mapping[k]]||''):'';return o});excelPicker(parsed)}}
function excelPicker(data){openModal('選取 ATM 異常案件',`<p class="subtext">勾選需要匯入的案件；日期與處理人將在下一步由你填寫。</p><div id="atmList">${data.map((r,i)=>`<div class="sourceitem"><label><input type="checkbox" data-atmselect="${i}"> <strong>${esc(r.location||'局名未提供')}　${esc(r.machine||'機號未提供')}</strong>　<span class="tag">${esc(r.status||'狀態未提供')}</span></label><p class="record-detail">${esc(r.description||'問題描述未提供')}</p></div>`).join('')}</div>`,`<button class="btn" id="modalCancel">取消</button><button class="btn primary" id="chooseATM">下一步：確認匯入</button>`,true);$('#chooseATM').onclick=()=>{let selectedRows=$$('[data-atmselect]:checked').map(x=>data[+x.dataset.atmselect]);if(!selectedRows.length)return modalError('請至少選擇一筆案件。');importReview(selectedRows.map(r=>({include:true,date:'',project:'other',projectConfirm:true,summary:r.description,progress:[r.status&&'狀態：'+r.status,r.analysis&&'廠商分析：'+r.analysis,r.solution&&'解決方法：'+r.solution].filter(Boolean).join('；'),people:[],vendor:r.vendor,isATM:true,source:'ATM Excel',milestoneName:'',milestoneValue:''})))}}
function recommendGroups(rows){let centers=rows.filter(r=>groups[r.id]!==undefined).map(r=>({name:groups[r.id]}));for(let r of rows){if(groups[r.id]!==undefined)continue;let x=centers.map(c=>({...c,score:sim(r.summary,c.name)})).sort((a,b)=>b.score-a.score)[0];let group=x?.score>=.67?x.name:r.summary;groups[r.id]=group;centers.push({name:group})}}
function getConflicts(){let conflicts=[];for(let p of store.projects){let own=selected().filter(r=>r.project===p.id&&r.scheduleProposal);let grouped={};for(let r of own){let q=r.scheduleProposal,k=q.name||'未指定里程碑';if(!grouped[k]||r.date>grouped[k].date)grouped[k]={...q,date:r.date,values:[q.value]};else if(r.date===grouped[k].date&&!grouped[k].values.includes(q.value))grouped[k].values.push(q.value)}for(let q of Object.values(grouped)){if(q.values.length>1){conflicts.push({projectId:p.id,pname:p.name,ambiguous:true,proposal:q});continue}let m=(p.milestones||[]).find(x=>x.name===q.name);if(!m||m.value!==q.value)conflicts.push({projectId:p.id,pname:p.name,proposal:q,milestone:m})}}return conflicts}
function renderReport(){let sel=selected(),atms=sel.filter(r=>r.isATM);recommendGroups(atms);let unique=[...new Set(atms.map(r=>groups[r.id]||r.summary))];let conflicts=getConflicts();sel.forEach(r=>{if(!architecture[r.id])architecture[r.id]={enabled:/(架構|功能範圍|系統設計).{0,12}(變更|調整|修改)|(?:變更|調整|修改).{0,12}(架構|功能範圍|系統設計)/.test(r.summary+' '+r.progress),before:'',after:'',impact:''}});$('#content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>整理本週週報</h2><p>依序確認紀錄、異常影響及時程，再建立交給 AI 的 Prompt。</p></div><span class="pill">${roc(weekStart)} — ${roc(weekEnd)}</span></div><div class="step"><span class="num">1</span><div><h3>確認本週重點</h3><p>已勾選 ${sel.length} 筆。固定專案未勾選進度時顯示「本週無特別事項」。</p></div></div>${conflicts.length?`<div class="notice warning"><strong>時程有待確認：</strong>${esc(conflicts.map(c=>c.pname).join('、'))}。產生前請決定採用哪個時間。</div>`:''}<div class="step"><span class="num">2</span><div><h3>合併同類 ATM 異常</h3><p>已推薦分組；可將紀錄的組名修改成相同或不同，完成合併或拆分。</p></div></div>${atms.length?`<div class="hint">${atms.map(r=>`<div class="field"><label>${esc(r.summary)}</label><input type="text" data-group="${r.id}" value="${esc(groups[r.id])}" aria-label="故障分組"></div>`).join('')}<button class="btn" id="refreshGroups">確認分組並填寫影響</button></div><div id="guides">${unique.map((g,i)=>guideCard(g,i)).join('')}</div>`:'<div class="hint">本週未勾選 ATM 異常，不需要填寫故障影響引導。</div>'}<div class="step"><span class="num">3</span><div><h3>確認功能或架構變更</h3><p>依關鍵字推薦，請自行勾選或取消，再補充前後規劃及影響。</p></div></div>${sel.length?sel.map(r=>architectureCard(r)).join(''):'<div class="hint">勾選紀錄後，可在這裡確認是否涉及功能或架構變更。</div>'}<div class="step"><span class="num">4</span><div><h3>預覽並編輯 Prompt</h3><p>每個專案獨立區塊，複製時合併；AI 產生 Word 或可複製表格。</p></div></div><div class="actions"><button class="btn primary" id="buildReport">產生週報 Prompt</button><button class="btn" id="reviewRecords">返回紀錄</button></div></section><div id="promptDisplay">${promptParts?promptView():''}</div>`;
$('#reviewRecords').onclick=()=>switchPage('records');if($('#refreshGroups'))$('#refreshGroups').onclick=()=>{$$('[data-group]').forEach(x=>groups[x.dataset.group]=x.value.trim()||store.records.find(r=>r.id===x.dataset.group).summary);renderReport()};bindGuides(unique);bindArchitecture();$('#buildReport').onclick=()=>run(buildReport);if(promptParts)bindPrompt()}
function guideCard(g,i){let v=guideValues[g]||{};return `<div class="guide" data-guide="${i}"><h3 style="margin:0 0 6px">${esc(g)}</h3><p class="helper">同組 ${selected().filter(r=>r.isATM&&groups[r.id]===g).length} 筆異常；請提供整體情況。</p><div class="formgrid"><div class="field"><label>規模判斷 *</label><select data-g="size" data-i="${i}"><option value="">請選擇</option>${['零星','大量'].map(x=>`<option ${v.size===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>統計母體 *</label><input data-g="scope" data-i="${i}" value="${esc(v.scope||'')}" placeholder="例如某廠商所有 ATM"></div><div class="field"><label>統計時點（選填）</label><input data-g="point" data-i="${i}" value="${esc(v.point||'')}" placeholder="例如目前、事故高峰時"></div><div class="field"><label>異常台數 *</label><input type="number" min="0" data-g="bad" data-i="${i}" value="${esc(v.bad??'')}"></div><div class="field"><label>母體總台數 *</label><input type="number" min="1" data-g="total" data-i="${i}" value="${esc(v.total??'')}"></div><div class="field"><label>確認正常的台數 *</label><input type="number" min="0" data-g="normal" data-i="${i}" value="${esc(v.normal??'')}"><small>不會自動假設其他機器都正常。</small></div><div class="field"><label>地區分布 *</label><input data-g="region" data-i="${i}" value="${esc(v.region||'')}" placeholder="北部、中部；集中縣市可寫明"></div><div class="field"><label>持續時間 *</label><input data-g="duration" data-i="${i}" value="${esc(v.duration||'')}" placeholder="例如約30分鐘、持續中"></div><div class="field"><label>客戶交易影響 *</label><select data-g="customer" data-i="${i}"><option value="">請選擇</option>${['有影響','無影響','待確認'].map(x=>`<option ${v.customer===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>交易影響說明／待確認單位與回覆時間</label><input data-g="customerDetail" data-i="${i}" value="${esc(v.customerDetail||'')}" placeholder="若待確認，請填單位與時間或尚未提供"></div><div class="field"><label>帳務影響 *</label><select data-g="account" data-i="${i}"><option value="">請選擇</option>${['有影響','無影響','待確認'].map(x=>`<option ${v.account===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>帳務影響說明／待確認單位與回覆時間</label><input data-g="accountDetail" data-i="${i}" value="${esc(v.accountDetail||'')}" placeholder="若待確認，請填單位與時間或尚未提供"></div><div class="field"><label>目前處理狀況 *</label><input data-g="handling" data-i="${i}" value="${esc(v.handling||'')}" placeholder="已排除、處理中及下一步"></div><div class="field"><label>已知關注或通報管道（選填）</label><input data-g="channels" data-i="${i}" value="${esc(v.channels||'')}" placeholder="社群、內部討論區、總經理室、新聞媒體"></div></div></div>`}
function bindGuides(unique){$$('[data-g]').forEach(x=>{let ev=x.tagName==='SELECT'?'change':'input';x.addEventListener(ev,()=>{let g=unique[+x.dataset.i];guideValues[g]=guideValues[g]||{};guideValues[g][x.dataset.g]=x.value;promptParts=null;let view=$('#promptDisplay');if(view)view.innerHTML=''})})}
function checkGuides(){for(let r of selected().filter(x=>x.isATM)){if(!groups[r.id]?.trim())throw Error('請確認每筆 ATM 異常的分組。')}let gs=[...new Set(selected().filter(x=>x.isATM).map(r=>groups[r.id]))];for(let name of gs){let v=guideValues[name]||{};if(!v.size||!String(v.scope||'').trim()||v.bad===undefined||v.bad===''||v.total===undefined||v.total===''||v.normal===undefined||v.normal===''||!v.region?.trim()||!v.duration?.trim()||!v.customer||!v.account||!v.handling?.trim())throw Error(`「${name}」的規模、統計數量、地區、持續時間、交易及帳務影響、處理狀況需填妥。`);let a=Number(v.bad),b=Number(v.total),n=Number(v.normal);if(!Number.isInteger(a)||!Number.isInteger(b)||!Number.isInteger(n)||a<0||n<0||b<=0||a+n>b)throw Error(`「${name}」的異常數與母體總數不合理。`);if(v.customer!=='無影響'&&!v.customerDetail?.trim())throw Error(`請補充「${name}」的交易影響或待確認單位及時間。`);if(v.account!=='無影響'&&!v.accountDetail?.trim())throw Error(`請補充「${name}」的帳務影響或待確認單位及時間。`)}return gs}
async function buildReport(){if($$('[data-group]').some(x=>x.value.trim()!==(groups[x.dataset.group]||''))){alert('分組已修改，請先按「確認分組並填寫影響」。');return}if(!selected().length){alert('請先勾選本週要列入的紀錄。');return}try{checkGuides();checkArchitecture()}catch(e){alert(e.message);return}let unresolved=store.projects.filter(p=>(p.milestones||[]).length&&!p.milestoneSelectionSet);if(unresolved.length){milestonePicker(unresolved);return}let conflicts=getConflicts();let ambiguous=conflicts.find(c=>c.ambiguous);if(ambiguous){alert('「'+ambiguous.pname+'」同一天有不同的里程碑時程。請回紀錄編輯該筆的「本筆提到的新時程」，確認正確後再產生週報。');return}if(conflicts.length){conflictModal(conflicts);return}preparePrompt()}
function conflictModal(cs){openModal('確認週報採用的時程',`<p class="subtext">紀錄與專案主檔的時程不同；請選擇里程碑並決定採用的時間。確認後專案主檔也會更新。</p>${cs.map((c,i)=>`<div class="sourceitem"><h3>${esc(c.pname)}</h3><div class="field"><label>里程碑</label><select data-conflict-mid="${i}"><option value="">請選擇</option>${(store.projects.find(p=>p.id===c.projectId)?.milestones||[]).map(m=>`<option value="${esc(m.id)}" ${m.id===c.milestone?.id?'selected':''}>${esc(m.name)}：${esc(m.value)}</option>`).join('')}</select></div><div class="field"><label>本次採用時程</label><select data-conflict-choice="${i}"><option value="">請選擇</option><option value="current">保留主檔時程</option><option value="new">紀錄中的新時程：${esc(c.proposal.value)}</option></select></div></div>`).join('')}`,`<button class="btn" id="modalCancel">取消</button><button class="btn primary" id="resolveTimes">確認並產生</button>`,true);$('#resolveTimes').onclick=async()=>{let changed=new Map(),resolutions=[];for(let i=0;i<cs.length;i++){let c=cs[i],mid=$(`[data-conflict-mid="${i}"]`).value,choice=$(`[data-conflict-choice="${i}"]`).value;if(!mid||!choice)return modalError('每個衝突都要選擇里程碑與採用的時程。');let p=changed.get(c.projectId)||structuredClone(store.projects.find(x=>x.id===c.projectId)),m=p.milestones.find(x=>x.id===mid);if(choice==='new'&&m.updatedOn&&c.proposal.date<m.updatedOn)return modalError('這筆紀錄比目前時程舊，不能覆蓋較新的時程；請保留主檔時程。');resolutions.push({projectId:p.id,name:m.name,value:choice==='new'?c.proposal.value:m.value,sourceValue:c.proposal.value});if(choice==='new'&&m.value!==c.proposal.value){m.changes=m.changes||[];m.changes.push({date:today,old:m.value,new:c.proposal.value});m.value=c.proposal.value;m.updatedOn=today;changed.set(p.id,p)}}try{if(changed.size)await saveBatch([...changed.values()].map(obj=>({kind:'projects',obj})));closeModal();reportResolutions=resolutions;preparePrompt()}catch(e){modalError(e.message)}}}
function guidanceText(name){let v=guideValues[name],pct=Number(v.bad)/Number(v.total)*100,shown=pct>0&&pct<.05?'<0.1':pct.toFixed(1),normal=Number(v.normal),remaining=Number(v.total)-Number(v.bad)-normal,np=normal/Number(v.total)*100,nshow=np>0&&np<.05?'<0.1':np.toFixed(1);return `【${name}：整體異常補充】\n規模：${v.size}；統計母體：${v.scope}${v.point?'；統計時點：'+v.point:''}；異常 ${v.bad} / ${v.total} 台（${shown}%）；確認正常 ${normal} / ${v.total} 台（${nshow}%）${remaining?'；其他或尚未確認 '+remaining+' 台':''}；地區：${v.region}；持續：${v.duration}。\n客戶交易：${v.customer}${v.customerDetail?'，'+v.customerDetail:''}。帳務：${v.account}${v.accountDetail?'，'+v.accountDetail:''}。目前處理：${v.handling}。${v.channels?'已知關注或通報管道：'+v.channels+'。':''}`}
function preparePrompt(){let sel=selected(),gs=[...new Set(sel.filter(r=>r.isATM).map(r=>groups[r.id]))],filename=`${String(Number(weekEnd.slice(0,4))-1911)}${weekEnd.slice(5,7)}${weekEnd.slice(8,10)}_週報_宏全.docx`;
let common=`請依以下素材撰寫給長官的專案進度週報。週報期間：${roc(weekStart)} 至 ${roc(weekEnd)}。\n\n【要求】\n1. 使用兩欄表格：「項目」與「本週處理（發生）重要工作事項」。項目顯示需求號、專案名稱及已選擇顯示的時程。無入選事項的固定專案寫「本週無特別事項」；沒有其他事項則不顯示補充其它。\n2. 優先呈現時程延誤或異動、功能範圍或系統架構改變、重大風險與異常、需長官協助或決策、以及已達成的重要里程碑。先結論或影響，再補處理細節；同一專案的重點依重要程度排序。\n3. 合併同專案的多筆內容，且每項能正確辨識處理人。需協助時說清楚希望長官做什麼；卡點與等待單位以素材為準。同類 ATM 異常整體敘述，保留已提供的數量、母體、異常與已確認正常比例、地區與已知通報管道；不逐一列郵局或機號，地區以北中南或特定集中縣市呈現。\n4. 只依提供的事實，保留專業名稱、交易代號，不推測或虛構；區分已發生影響與可能風險。矛盾或不足保留原文供確認。時程異動採週初原訂 → 最後確認；無法取得原始時間時不得猜測。\n5. 不累積前週歷史；當週紀錄明確提到的下一步可列出。日期採民國年月日，精確日期未知時保留原有精度。風格參照精簡、直接的專案週報。\n6. 對勾選但不夠重要的例行事項，另在對話中列「建議不列入」供確認，不放進正式 Word。\n7. 請產生可下載 Word 檔「${filename}」；若無法產檔，請提供可複製到 Word 的兩欄表格。\n\n【週報素材】`;
let parts=[{key:'common',projectId:null,title:'共通指令',text:common}];for(let p of store.projects){let rs=sel.filter(r=>r.project===p.id),ms=(p.milestones||[]).filter(m=>m.show).map(m=>`${m.name}：${m.value}`);let changes=(p.milestones||[]).flatMap(m=>{let c=(m.changes||[]).filter(x=>x.date>=weekStart&&x.date<=weekEnd).sort((a,b)=>a.date.localeCompare(b.date));return c.length?[`${m.name}時程異動：${c[0].old} → ${c.at(-1).new}`]:[]});let arch=rs.filter(r=>architecture[r.id]?.enabled).map(r=>`【功能／架構變更：${r.summary}】原規劃：${architecture[r.id].before}；變更後：${architecture[r.id].after}；影響：${architecture[r.id].impact}`).join('\n');let t=`【${p.name}】${p.request?'\n需求號：'+p.request:''}${ms.length?'\n預計時程：'+ms.join('；'):''}${changes.length?'\n'+changes.join('；'):''}${reportResolutions.filter(x=>x.projectId===p.id).length?'\n時程衝突已由使用者確認（請以此為準，不要因素材的舊提案自行變更）：'+reportResolutions.filter(x=>x.projectId===p.id).map(x=>x.name+'：'+x.value).join('；'):''}\n`+(rs.length?rs.map(r=>`- ${roc(r.date)}｜${r.summary}｜${r.progress}｜處理人：${(r.people||[]).join('、')}${r.vendor?'｜廠商或外部人員：'+r.vendor:''}`).join('\n'):'本週無特別事項');let relevant=gs.filter(g=>rs.some(r=>r.isATM&&groups[r.id]===g));if(relevant.length)t+='\n\n'+relevant.map(guidanceText).join('\n\n');if(arch)t+='\n\n'+arch;parts.push({key:p.id,projectId:p.id,title:p.name,text:t})}let other=sel.filter(r=>r.project==='other');if(other.length){let t='【補充其它】\n'+other.map(r=>`- ${roc(r.date)}｜${r.summary}｜${r.progress}｜處理人：${r.people.join('、')}${r.vendor?'｜廠商或外部人員：'+r.vendor:''}`).join('\n');let rel=gs.filter(g=>other.some(r=>r.isATM&&groups[r.id]===g));if(rel.length)t+='\n\n'+rel.map(guidanceText).join('\n\n');let arch=other.filter(r=>architecture[r.id]?.enabled).map(r=>`【功能／架構變更：${r.summary}】原規劃：${architecture[r.id].before}；變更後：${architecture[r.id].after}；影響：${architecture[r.id].impact}`).join('\n');if(arch)t+='\n\n'+arch;parts.push({key:'other',projectId:'other',title:'補充其它',text:t})}promptParts=parts;renderReport();document.getElementById('promptDisplay').scrollIntoView({behavior:'smooth'})}
function promptView(){return `<section class="panel"><div class="panel-head"><div><h2>Prompt 預覽與編輯</h2><p>請將專案內容保留在各自區塊；共通指令不要加入個別專案資料。</p></div><button class="btn primary" id="copyPrompt">複製 Prompt</button></div>${promptParts.map((p,i)=>`<div class="field"><label>${esc(p.title)}</label><textarea data-part="${i}" rows="${p.key==='common'?10:5}">${esc(p.text)}</textarea></div>`).join('')}</section>`}
function bindPrompt(){$$('[data-part]').forEach(t=>t.oninput=()=>promptParts[+t.dataset.part].text=t.value);$('#copyPrompt').onclick=()=>run(copyAndSave)}
async function copyAndSave(){if(!promptParts?.length)return;let old=store.history.find(x=>x.id===weekEnd);if(old&&!confirm('本週已有歷史 Prompt，要覆蓋為這次版本嗎？'))return;let text=promptParts.map(p=>p.text).join('\n\n');if(!(await copyText(text)))return;try{await saveEntity('history',{id:weekEnd,parts:structuredClone(promptParts),when:new Date().toISOString()});alert('Prompt 已複製，並保存到測試副本。')}catch(e){setStatus('Prompt 已複製，但歷史保存失敗：'+e.message,true);alert('Prompt 已複製，但歷史保存失敗。請重新登入後再試。')}}
function renderHistory(){$('#content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>歷史 Prompt</h2><p>同一週只保留最後一次複製的版本。</p></div></div>${store.history.length?store.history.slice().sort((a,b)=>b.id.localeCompare(a.id)).map(h=>`<div class="history"><div><strong>${roc(h.id)} 週報</strong><p>最近儲存：${esc(new Date(h.when).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}))}</p></div><button class="btn" data-history="${esc(h.id)}">查看</button></div>`).join(''):'<div class="empty"><b>還沒有保存的 Prompt</b>複製一份週報 Prompt 後，就會顯示在這裡。</div>'}</section>`;$$('[data-history]').forEach(b=>b.onclick=()=>{let h=store.history.find(x=>x.id===b.dataset.history);openModal('歷史 Prompt',`<p class="subtext">${roc(h.id)} 的最後快照。</p><textarea class="prompt-area" readonly>${esc((h.parts||[]).map(p=>p.text).join('\n\n'))}</textarea>`,`<button class="btn" id="modalCancel">關閉</button>`,true)})}
render();
function milestonePicker(projects){openModal('選擇週報顯示時程',`<p class="subtext">這些專案尚未設定要顯示的里程碑；選擇後會沿用，也可以全不選。</p>${projects.map((p,i)=>`<div class="sourceitem"><h3>${esc(p.name)}</h3>${p.milestones.map((m,j)=>`<label style="display:block;padding:5px"><input type="checkbox" data-mpick="${i}:${j}" ${m.show?'checked':''}> ${esc(m.name)}：${esc(m.value)}</label>`).join('')}</div>`).join('')}`,`<button class="btn" id="modalCancel">取消</button><button class="btn primary" id="saveMilestones">儲存選擇並繼續</button>`,true);$('#saveMilestones').onclick=async()=>{let updates=projects.map((p,i)=>({...p,milestoneSelectionSet:true,milestones:p.milestones.map((m,j)=>({...m,show:$(`[data-mpick="${i}:${j}"]`).checked}))}));try{await saveBatch(updates.map(obj=>({kind:'projects',obj})));closeModal();await buildReport()}catch(e){modalError(e.message)}}}

function architectureCard(r){let a=architecture[r.id];return `<div class="sourceitem"><label><input type="checkbox" data-arch-enabled="${esc(r.id)}" ${a.enabled?'checked':''}> 功能或架構變更：${esc(r.summary)}</label>${a.enabled?`<div class="formgrid"><div class="field"><label>原本規劃 *</label><input data-arch="before" data-rid="${esc(r.id)}" value="${esc(a.before)}"></div><div class="field"><label>變更後規劃 *</label><input data-arch="after" data-rid="${esc(r.id)}" value="${esc(a.after)}"></div><div class="field"><label>影響 *</label><input data-arch="impact" data-rid="${esc(r.id)}" value="${esc(a.impact)}" placeholder="可填待相關單位確認"></div></div>`:''}</div>`}
function bindArchitecture(){$$('[data-arch-enabled]').forEach(x=>x.onchange=()=>{architecture[x.dataset.archEnabled].enabled=x.checked;promptParts=null;renderReport()});$$('[data-arch]').forEach(x=>x.oninput=()=>{architecture[x.dataset.rid][x.dataset.arch]=x.value;promptParts=null;let v=$('#promptDisplay');if(v)v.innerHTML=''})}
function checkArchitecture(){for(let r of selected()){let a=architecture[r.id];if(a?.enabled&&(!a.before.trim()||!a.after.trim()||!a.impact.trim()))throw Error(`「${r.summary}」請補充原規劃、變更後規劃及影響；未知影響可如實填待確認。`)}}
